solutions.naive:
class Solution:
    def isPowerOfTwo(self, n: int) -> bool:
        if n <= 0:
            return False
        value = 1
        while value < n:
            value *= 2
        return value == n

solutions.better:
class Solution:
    def isPowerOfTwo(self, n: int) -> bool:
        if n <= 0:
            return False
        count = 0
        while n:
            count += n & 1
            n >>= 1
        return count == 1

solutions.optimal:
class Solution:
    def isPowerOfTwo(self, n: int) -> bool:
        return n > 0 and (n & (n - 1)) == 0

